import React, { useEffect, useRef } from 'react';

// Moved skills array outside the component to fix ESLint dependency warning (it's static, so no need for useState or useMemo)
const skills = [
  { icon: '☁️', title: 'Cloud', percent: 70 },
  { icon: '🐳', title: 'Containers', percent: 80 },
  { icon: '📜', title: 'IaC', percent: 80 },
  { icon: '⚙️', title: 'CI/CD', percent: 70 },
  { icon: '🐚', title: 'Scripting', percent: 60 },
  { icon: '🗂️', title: 'Version Control', percent: 70 },
  { icon: '🔒', title: 'Security', percent: 60 },
  { icon: '📈', title: 'Monitoring', percent: 80 },
];

const Skills = () => {
  // Create an array of refs for each skill circle (one per skill)
  const circleRefs = useRef(skills.map(() => React.createRef()));

  useEffect(() => {
    // Animate each circle after the component mounts
    circleRefs.current.forEach((ref, index) => {
      if (ref.current) {
        const progress = ref.current.querySelector('.progress');
        const percent = skills[index].percent;
        const radius = 45;
        const circumference = 2 * Math.PI * radius;
        const offset = circumference - (percent / 100) * circumference;

        progress.style.strokeDasharray = circumference;
        progress.style.strokeDashoffset = circumference;
        setTimeout(() => {
          progress.style.strokeDashoffset = offset;
        }, 500); // Delay for smooth animation
      }
    });
  }, []); // No dependencies needed since skills is static and refs are stable

  return (
    <section id="skills">
      <h2 className="section-title">My Skills</h2>
      <div className="skills-grid">
        {skills.map((skill, index) => (
          <div key={index} className="skill-card">
            <div className="skill-icon">{skill.icon}</div>
            <h3>{skill.title}</h3>
            <div className="skill-circle" ref={circleRefs.current[index]}>
              <svg width="100" height="100">
                <circle cx="50" cy="50" r="45" stroke="#2b2a26" strokeWidth="10" fill="none" />
                <circle className="progress" cx="50" cy="50" r="45" stroke="#d4a373" strokeWidth="10" fill="none" strokeLinecap="round" />
              </svg>
              <span>{skill.percent}%</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
};

export default Skills;
